import assert from 'node:assert/strict';
import {readFileSync,writeFileSync,mkdirSync} from 'node:fs';
import {dirname,resolve} from 'node:path';
import {pathToFileURL} from 'node:url';
import {invocation,makeRecordRef,parseDecimal,isDecimal,normalizeSchema,validateValue,decodeValue,encodeValue} from '@canlang/values';
import {invocation as publicInvocation} from '@canlang/stdlib';
assert.equal(invocation,publicInvocation);
const artifact=JSON.parse(readFileSync('artifact.json','utf8'));
const base=resolve('generated');
for(const module of artifact.modules){const file=resolve(base,module.path);mkdirSync(dirname(file),{recursive:true});writeFileSync(file,module.js);}
const entry=await import(pathToFileURL(resolve(base,artifact.modules.find(m=>m.js.includes('function canApp')).path)));
const registry=entry.canApp();
const context={memberships:['members'],actor:{id:'actor'}};
const call=(name,...args)=>{const item=artifact.callables.find(i=>i.id===`Invocations.${name}`);assert(item,name);let fn=registry;for(const key of item.member)fn=fn[key];return fn(context,...args);};
const record=makeRecordRef('Invocations.Item','w1');
const amount=parseDecimal('3.75');
const reads=[];
const result=await call('descriptors',{get record(){reads.push('record');return record;},get amount(){reads.push('amount');return amount;},get note(){reads.push('note');return 'authored';}});
assert.deepEqual(reads,['record','amount','note']);
assert.equal(result.local.target,'Invocations.mutate');assert.equal(result.local.kind,'invocation');
assert.deepEqual(result.local.args.record,record);assert.equal(result.local.args.record.version,undefined);
assert(isDecimal(result.local.args.amount));assert.equal(result.local.args.amount.coef,amount.coef);assert.equal(result.local.args.amount.scale,amount.scale);assert.equal(result.local.args.note,'authored');
assert.deepEqual(Object.keys(result.local.args),['note','amount','record']);
assert(Object.isFrozen(result.local));assert(Object.isFrozen(result.local.args));assert.equal(result.optional,null);
const authoredDefaults=await call('descriptors',{record});
assert.equal(authoredDefaults.local.args.amount.coef,250n);assert.equal(authoredDefaults.local.args.amount.scale,2);assert.equal(authoredDefaults.local.args.note,'hello');
await assert.rejects(()=>call('descriptors',{record,amount:3.75}),/must be a Can value/);
const inputs=entry.appDefinition.operations['Invocations.descriptors'].inputs;
const defaults=await call('descriptors',{record,amount:inputs.amount.default,note:inputs.note.default});
assert.equal(defaults.local.args.amount.coef,250n);assert.equal(defaults.local.args.amount.scale,2);assert.equal(defaults.local.args.note,'hello');
assert.deepEqual(await call('defaults',{}),invocation('Invocations.empty',{}));
// Read actual emitted contract fields rather than recreating their schema.
const fields=entry.appDefinition.contracts['Invocations.References'].fields;
assert.equal(fields.local.type,'invocation(Invocations.mutate)');
assert.deepEqual(fields.optional,{type:'invocation(Invocations.mutate)?'});
assert.deepEqual(fields.choices,{type:'invocation(Invocations.empty,Invocations.mutate)'});
assert.deepEqual(fields.many,{type:'invocation(Invocations.mutate)[]'});
assert.deepEqual(fields.required,{type:'invocation(Invocations.mutate)[]!'});
assert.deepEqual(fields.nullableMany,{type:'invocation(Invocations.mutate)[]?'});
const normalized=normalizeSchema({contracts:{Proposal:{fields}}});
const wire=encodeValue(fields.local.type,result.local);
assert.equal(wire.arguments.amount.type,'decimal');assert.equal(wire.arguments.amount.value,'3.75');
assert.deepEqual(decodeValue(fields.local.type,wire),result.local);
const proposalWire={local:wire,optional:null,choices:encodeValue(fields.choices.type,result.choices),many:encodeValue(fields.many.type,result.many),required:[],nullableMany:null};
const validated=validateValue(normalized,'Proposal',proposalWire,'create');
assert.deepEqual(validated,result);
assert.throws(()=>validateValue(normalized,'Proposal',{...proposalWire,required:undefined},'create'));
assert.deepEqual(decodeValue(fields.many.type,proposalWire.many),result.many);
assert.throws(()=>decodeValue(fields.local.type,{...wire,target:'Invocations.empty'}));
console.log('Generated invocation modules imported public stdlib; native record/Decimal, scalar/emitted-default-data/order/once construction and emitted schema normalize/validate/codec controls passed. No target executed or authority granted.');
